 const findSpace=id=>spaces.find(s=>s.id===id),findRoom=id=>rooms.find(r=>r.id===id);
 const allowed=w=>!!w&&!!findSpace(w.space)&&!!findRoom(w.room)&&canSpace(findSpace(w.space))&&canRoom(findRoom(w.room))&&[...w.members,...w.readers].includes(state.viewer);
